package com.codepilot1c.core.edt.development;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.nio.charset.StandardCharsets;import com.codepilot1c.core.tools.*;import java.util.concurrent.CompletableFuture;
public class AgentEfficiencyTest {
 static class Sample extends AbstractTool {final String name,description;Sample(String n,String d){name=n;description=d;}public String getName(){return name;}public String getDescription(){return description;}public String getParameterSchema(){return "{\"type\":\"object\",\"properties\":{}}";}protected CompletableFuture<ToolResult> doExecute(ToolParameters p){return CompletableFuture.completedFuture(ToolResult.success("{}"));}}
 @Test public void catalogOmitsRoutesAndSupportsMultiNameSchemasAndMissingNames(){var tools=List.<ITool>of(new Sample("b","B"),new Sample("a","A"));var out=CapabilityCatalog.describe(tools,Map.of("names",List.of("a","missing"),"include_schemas",true));assertFalse(out.containsKey("workflows"));assertEquals(List.of("missing"),out.get("missing_names"));assertEquals(1,((List<?>)out.get("tools")).size());assertTrue(TaskSessionService.object(((List<?>)out.get("tools")).get(0)).containsKey("schema"));assertTrue(CapabilityCatalog.describe(tools,Map.of("include_workflows",true)).containsKey("workflows"));}
 @Test public void catalogReceiptIgnoresRegistrationOrderAndInvalidatesDescription(){var a=new Sample("a","first");var b=new Sample("b","second");String hash=(String)CapabilityCatalog.describe(List.of(a,b),Map.of()).get("catalog_sha256");assertEquals(hash,CapabilityCatalog.describe(List.of(b,a),Map.of()).get("catalog_sha256"));assertEquals(true,CapabilityCatalog.describe(List.of(a,b),Map.of("if_catalog_sha256",hash)).get("not_modified"));assertNotEquals(hash,CapabilityCatalog.describe(List.of(new Sample("a","changed"),b),Map.of()).get("catalog_sha256"));}
 @Test public void projectedViewKeepsEvidenceAndExactNullInRecoverableDetails(){var in=new LinkedHashMap<String,Object>();in.put("state","completed");in.put("runtime_verified",false);in.put("payload","x".repeat(6000));in.put("explicit_null",null);var out=AgentResponses.view(in,Map.of("view","summary","max_bytes",1024));var data=TaskSessionService.object(out.get("data"));assertEquals(false,data.get("runtime_verified"));var meta=TaskSessionService.object(out.get("response"));assertEquals(false,meta.get("complete"));String id=(String)meta.get("details_id");StringBuilder text=new StringBuilder();int offset=0;for(;;){var page=AgentResponses.read(id,offset,500);text.append(page.get("text"));offset=((Number)page.get("next_offset")).intValue();if(!Boolean.TRUE.equals(page.get("has_more")))break;}var recovered=AgentResponses.JSON.fromJson(text.toString(),LinkedHashMap.class);assertTrue(recovered.containsKey("explicit_null"));assertNull(recovered.get("explicit_null"));assertEquals(in.get("payload"),recovered.get("payload"));assertTrue(AgentResponses.JSON.toJson(out).getBytes(StandardCharsets.UTF_8).length<=1024);}
 @Test public void projectionDoesNotMutateSourceAndKeepsCompleteness(){var original=Map.<String,Object>of("success",true,"has_more",true,"text","a".repeat(4000));var out=AgentResponses.view(original,Map.of("fields",List.of("text"),"max_bytes",1024));assertEquals(true,TaskSessionService.object(out.get("data")).get("has_more"));assertEquals(4000,((String)original.get("text")).length());assertEquals(true,TaskSessionService.object(out.get("response")).get("truncated"));assertThrows(IllegalArgumentException.class,()->AgentResponses.view(original,Map.of("max_bytes",12)));assertThrows(IllegalArgumentException.class,()->AgentResponses.read("missing",0,100));}
 @Test public void detailsPaginationPreservesSurrogatePairs(){var out=AgentResponses.view(Map.of("emoji","😀".repeat(20)),Map.of("view","summary"));String id=(String)TaskSessionService.object(out.get("response")).get("details_id");StringBuilder text=new StringBuilder();int offset=0;for(;;){var page=AgentResponses.read(id,offset,3);String part=(String)page.get("text");if(!part.isEmpty())assertFalse(Character.isHighSurrogate(part.charAt(part.length()-1)));text.append(part);offset=((Number)page.get("next_offset")).intValue();if(!Boolean.TRUE.equals(page.get("has_more")))break;}assertEquals("😀".repeat(20),TaskSessionService.object(AgentResponses.JSON.fromJson(text.toString(),Map.class)).get("emoji"));}
 @Test public void errorsNeverAuthorizeUnknownWrites(){var out=AgentErrors.describe("test","sync",new IllegalArgumentException("Infobase base is already connected"),false);assertEquals("already_connected",out.get("reason"));assertEquals(false,out.get("retry_safe"));assertEquals("not_proven",out.get("execution_state"));assertEquals("outcome_unknown",AgentErrors.describe("test","step",new IllegalStateException("outcome_unknown"),false).get("reason"));}
 @Test public void compactJobIncludesIdsButNoCode(){var out=AgentBrief.operation(Map.of("job_id","j","state","DONE","terminal",true,"result",Map.of("host_id","h","artifact_sha256","hash","code","SECRET","cleaned",false)));var result=TaskSessionService.object(out.get("result"));assertEquals("h",result.get("host_id"));assertEquals(false,result.get("cleaned"));assertFalse(result.containsKey("code"));}
 @Test public void metricsContainCountersWithoutPayloadsOrTokenClaims(){AgentMetrics.record("test-metric",10,20,30,false);var out=AgentMetrics.snapshot();assertEquals(false,out.get("token_usage_measured"));assertFalse(AgentResponses.JSON.toJson(out).contains("arguments"));assertTrue(((Number)out.get("calls")).longValue()>0);}

 @Test public void invalidResponseOptionsAreRejectedBeforeMutation()throws Exception{var actions=new java.util.concurrent.atomic.AtomicInteger();var tool=new Sample("mutate","fixture"){protected CompletableFuture<ToolResult> doExecute(ToolParameters p){actions.incrementAndGet();return CompletableFuture.completedFuture(ToolResult.success("{}"));}};assertFalse(tool.execute(Map.of("response",Map.of("max_bytes",1))).get().isSuccess());assertEquals(0,actions.get());}
 @Test public void oversizedEvidenceReturnsDetailsRequiredInsteadOfFalseOperationFailure(){var value=Map.<String,Object>of("state","completed","error","x".repeat(5000));var out=AgentResponses.view(value,Map.of("max_bytes",1024));assertEquals("details_required",TaskSessionService.object(out.get("data")).get("state"));assertEquals(false,TaskSessionService.object(out.get("response")).get("complete"));}
 @Test public void responseBoundsRejectFractionsAndOverflow(){assertThrows(IllegalArgumentException.class,()->AgentResponses.integer(Map.of("limit",new java.math.BigDecimal("1.5")),"limit",1,0,100));assertThrows(IllegalArgumentException.class,()->AgentResponses.validateOptions(Map.of("max_bytes",new java.math.BigDecimal("18446744073709552640"))));}
 @Test public void summaryPreservesNestedFailedExecutionAndIncompleteChecks(){var value=Map.<String,Object>of("state","DONE","terminal",true,"result",Map.of("execution",Map.of("success",false,"error","failed","code","OMIT"),"partial_restore",true),"changes",Map.of("runtime_verified",false,"file_comparison_complete",false,"files",List.of("large")));var out=AgentResponses.view(value,Map.of("view","summary"));var data=TaskSessionService.object(out.get("data"));var result=TaskSessionService.object(data.get("result"));assertEquals(false,TaskSessionService.object(result.get("execution")).get("success"));assertEquals(true,result.get("partial_restore"));assertEquals(false,TaskSessionService.object(data.get("changes")).get("runtime_verified"));assertFalse(TaskSessionService.object(result.get("execution")).containsKey("code"));assertEquals(false,TaskSessionService.object(out.get("response")).get("complete"));}
 @Test public void compactOperationPreservesNestedExecutionFailure(){var out=AgentBrief.operation(Map.of("job_id","j","state","DONE","result",Map.of("execution",Map.of("success",false,"error","failed","code","OMIT"))));var execution=TaskSessionService.object(TaskSessionService.object(out.get("result")).get("execution"));assertEquals(false,execution.get("success"));assertFalse(execution.containsKey("code"));}
 @Test public void catalogReceiptAndSchemasPreserveLargeIntegerBounds(){var a=new Sample("precise","number"){public String getParameterSchema(){return "{\"type\":\"object\",\"properties\":{\"limit\":{\"type\":\"integer\",\"maximum\":9007199254740992}}}";}};var b=new Sample("precise","number"){public String getParameterSchema(){return "{\"type\":\"object\",\"properties\":{\"limit\":{\"type\":\"integer\",\"maximum\":9007199254740993}}}";}};var first=CapabilityCatalog.describe(List.of(a),Map.of());var second=CapabilityCatalog.describe(List.of(b),Map.of("include_schemas",true));assertNotEquals(first.get("catalog_sha256"),second.get("catalog_sha256"));var schema=TaskSessionService.object(TaskSessionService.object(((List<?>)second.get("tools")).get(0)).get("schema"));Object maximum=TaskSessionService.object(TaskSessionService.object(schema.get("properties")).get("limit")).get("maximum");assertEquals(new java.math.BigDecimal("9007199254740993"),maximum);}
 @Test public void depthLimitNeverFallsBackToRawPayload(){Map<String,Object> nested=Map.of("success",false,"code","SECRET_CODE","logs","SECRET_LOG");for(int i=0;i<20;i++)nested=Map.of("nested",nested);var out=AgentBrief.operation(Map.of("job_id","j","state","DONE","result",nested));String text=AgentResponses.JSON.toJson(out);assertFalse(text.contains("SECRET_CODE"));assertFalse(text.contains("SECRET_LOG"));assertTrue(text.contains("evidence_complete"));assertTrue(text.contains("evidence_truncated"));}
 @Test public void nestedEvidenceListsAndBoundedErrorsArePreserved(){var out=AgentBrief.operation(Map.of("job_id","j","state","DONE","result",Map.of("execution",Map.of("success",false,"error","x".repeat(5000),"unknown_sections",List.of("database"),"blockers",List.of("ownership_unverified")),"value",Map.of("error","SECRET_VALUE"))));var result=TaskSessionService.object(out.get("result"));var execution=TaskSessionService.object(result.get("execution"));assertEquals(List.of("database"),execution.get("unknown_sections"));assertEquals(List.of("ownership_unverified"),execution.get("blockers"));assertEquals(1024,((String)execution.get("error")).length());assertEquals(true,execution.get("error_truncated"));assertEquals(false,execution.get("evidence_complete"));assertFalse(AgentResponses.JSON.toJson(out).contains("SECRET_VALUE"));}
 @Test public void explicitFieldProjectionCannotDropNestedFailureToMeetBudget(){var out=AgentResponses.view(Map.of("state","DONE","result",Map.of("execution",Map.of("success",false),"payload","x".repeat(5000))),Map.of("fields",List.of("result"),"max_bytes",1024));var data=TaskSessionService.object(out.get("data"));assertTrue("details_required".equals(data.get("state"))||Boolean.FALSE.equals(TaskSessionService.object(TaskSessionService.object(data.get("result")).get("execution")).get("success")));}
}
